#!/usr/bin/env python3
import base64
import hashlib
import lzma
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
EXPECTED_SHA256 = "427dbc2d495fb3f9676f06679e6897594684deef006fbe39669fc559b247eca0"
PAYLOAD_B64 = r''''''


class StageCReviseEarly16ExactBytesTest(unittest.TestCase):
    def test_exact_bytes_pass_current_main_stage_c_contracts(self):
        raw = lzma.decompress(base64.b64decode(PAYLOAD_B64))
        self.assertEqual(hashlib.sha256(raw).hexdigest(), EXPECTED_SHA256)
        with tempfile.TemporaryDirectory() as tmp:
            artifact = Path(tmp) / "stage_c_revise_r1.json"
            artifact.write_bytes(raw)

            artifact_check = subprocess.run(
                [sys.executable, "validation_scripts/stage_artifact_contract_check.py", "C", str(artifact)],
                cwd=ROOT,
                text=True,
                capture_output=True,
            )
            self.assertEqual(artifact_check.returncode, 0, artifact_check.stdout + artifact_check.stderr)
            self.assertIn('"status": "PASS"', artifact_check.stdout)
            self.assertIn('"item_count": 5', artifact_check.stdout)
            self.assertIn('"missing_count": 0', artifact_check.stdout)

            lineage_check = subprocess.run(
                [sys.executable, "validation_scripts/stage_lineage_contract_check.py", "stage_c", str(artifact)],
                cwd=ROOT,
                text=True,
                capture_output=True,
            )
            self.assertEqual(lineage_check.returncode, 0, lineage_check.stdout + lineage_check.stderr)
            self.assertIn("PASS_STAGE_C_SCHEMA_CONTRACT", lineage_check.stdout)


if __name__ == "__main__":
    unittest.main()
